TUNING_SEEDS = [101, 202, 303]
STABILITY_PENALTY = 0.25
N_TRIALS = 40
NEURAL_EPOCHS = 120
NEURAL_PATIENCE = 15
EXPERIMENTS = ["early_warning", "enhanced_supervision"]
